static inline Str gorget_char_chr(int64_t code) { return gorget_str_from_cstr(gorget_codepoint_to_utf8(code)); }
static inline Str gorget_str_default(void) { return (Str){NULL, 0, 0, NULL}; }
static inline int64_t int64_t__default(void) { return 0; }
static inline int64_t int__default(void) { return 0; }
static inline int8_t int8_t__default(void) { return 0; }
static inline int16_t int16_t__default(void) { return 0; }
static inline int32_t int32_t__default(void) { return 0; }
static inline uint8_t uint8_t__default(void) { return 0; }
static inline uint16_t uint16_t__default(void) { return 0; }
static inline uint32_t uint32_t__default(void) { return 0; }
static inline uint64_t uint64_t__default(void) { return 0; }
static inline double double__default(void) { return 0.0; }
static inline double float__default(void) { return 0.0; }
static inline bool bool__default(void) { return false; }
static inline int64_t __gorget_hash_int(int64_t v) { return (int64_t)__gorget_fnv1a(&v, sizeof(v)); }
static inline int64_t gorget_str_hash(Str s) { return (int64_t)__gorget_hash_str_len(s.data, s.len); }
#ifndef _WIN32
#include <signal.h>
#endif
